def edit_distance(a: str, b: str) -> int:
    if len(a) > len(b):
        a, b = b, a

    if not a:
        return len(b)

    m = len(a)
    dp = list(range(m + 1))

    for i, ch_b in enumerate(b, 1):
        prev_diag = dp[0]
        dp[0] = i

        for j, ch_a in enumerate(a, 1):
            old = dp[j]
            cost = 0 if ch_a == ch_b else 1
            dp[j] = min(old + 1, dp[j - 1] + 1, prev_diag + cost)
            prev_diag = old

    return dp[m]
```

